(8, 1, 1, 1, 1, 4, 1, N'SP08', N'Vợt cầu lông Yonex Astrox 100ZZ VA', N'Phiên bản chữ ký Viktor Axelsen, khung siêu cứng nặng đầu cho những cú đập uy lực. Dành cho người chơi trình độ cao.', '2025-09-27T10:00:00', '2025-09-27T10:00:00', 1),
