(10, 1, 1, 1, 1, 2, 1, N'SP10', N'Vợt cầu lông Yonex Astrox 77 Tour Limited', N'Bản giới hạn màu Light Beige, nặng đầu nhẹ, dễ đánh cả công lẫn thủ.', '2025-09-27T10:00:00', '2025-09-27T10:00:00', 1),
(11, 1, 1, 1, 1, 2, 2, N'SP11', N'Vợt cầu lông Yonex Arcsaber 7 Play Limited', N'Cân bằng, đũa dẻo vừa, giữ cầu lâu trên mặt lưới giúp điều cầu chính xác.', '2025-09-27T10:00:00', '2025-09-27T10:00:00', 1),
(12, 1, 1, 1, 1, 3, 3, N'SP12', N'Vợt cầu lông Yonex Nanoflare 700 Pro 2024', N'Nhẹ đầu, khung mỏng cắt gió, phản tạt và chặn lưới cực nhanh.', '2025-09-27T10:00:00', '2025-09-27T10:00:00', 1),
(13, 1, 2, 2, 1, 3, 2, N'SP13', N'Vợt cầu lông Lining Halbertec 9000 Power', N'Dòng cao cấp của Lining, cân bằng giữa lực và tốc độ, cảm giác đánh chắc tay.', '2025-09-27T10:00:00', '2025-09-27T10:00:00', 1),
(14, 1, 2, 2, 1, 3, 3, N'SP14', N'Vợt cầu lông Lining Bladex 800 Speed 2026', N'Khung dạng lưỡi dao giảm lực cản, thiên về tốc độ cho lối đánh đôi.', '2025-09-27T10:00:00', '2025-09-27T10:00:00', 1),
(15, 1, 2, 2, 1, 4, 1, N'SP15', N'Vợt cầu lông Lining Axforce 100 Gen 2', N'Siêu nặng đầu, đũa rất cứng, đường cầu cắm sâu. Dành cho người có lực cổ tay tốt.', '2025-09-27T10:00:00', '2025-09-27T10:00:00', 1),
