(17, 1, 3, 3, 1, 3, 1, N'SP17', N'Vợt cầu lông Victor Thruster F C Ultra', N'Dòng Thruster nặng đầu, đập cầu nặng và sâu, khung chắc chắn.', '2025-09-27T10:00:00', '2025-09-27T10:00:00', 1),
