(19, 1, 3, 3, 1, 3, 3, N'SP19', N'Vợt cầu lông Victor Auraspeed 100X 2026', N'Nhẹ đầu, khung khí động học cho tốc độ vung vợt nhanh.', '2025-09-27T10:00:00', '2025-09-27T10:00:00', 1),
