(3, 3, 3, NULL, N'Trợ lý ảo', N'Xin chào Lê Quốc Tuấn! Mình là trợ lý ảo của FootStyle. Mình có thể giúp bạn:
• Tìm vợt, phụ kiện theo hãng, giá, lối chơi (vd: "vợt Yonex dưới 3 triệu", "vợt tấn công 4U")
• Xem khuyến mãi, mã giảm giá đang có
• Kiểm tra đơn hàng (gửi mã đơn, vd: HD12)
• Giải đáp giao hàng, đổi trả, thanh toán
Cần nói chuyện với nhân viên thì bấm "Gặp nhân viên" nhé.', '2026-11-02T14:54:01'),
(4, 4, 2, 1, N'Nguyễn Hoàng Long', N'lo', '2026-11-03T20:03:50'),
(5, 3, 1, NULL, N'Lê Quốc Tuấn', N'Vợt dưới 3 triệu', '2026-11-10T21:56:42'),
(6, 3, 3, NULL, N'Trợ lý ảo', N'Sản phẩm còn hàng phù hợp (vợt, giá dưới 3.000.000 ₫):
• Vợt cầu lông Kumpoo AK7 II (Kumpoo, cân bằng): 513.500 ₫ - 578.500 ₫ (đang giảm 35%) · Trắng · 4U (80-84g) · G5, Trắng · 5U (75-79g) · G5
• Vợt cầu lông Kumpoo QF-12 (Kumpoo, cân bằng): 607.200 ₫ (đang giảm 12%) · Trắng · 4U (80-84g) · G5, Trắng · 5U (75-79g) · G5
• Vợt cầu lông Lining Halbertec 1000 (Lining, cân bằng): 880.000 ₫ · Trắng · 4U (80-84g) · G5, Trắng · 5U (75-79g) · G5
• Vợt cầu lông Yonex Astrox 10 (Yonex, cân bằng): 939.000 ₫ · Trắng · 4U (80-84g) · G5, Trắng · 5U (75-79g) · G5
• Vợt cầu lông Lining Axforce 10 (Lining, nặng đầu): 950.000 ₫ · Đen · 4U (80-84g) · G5, Trắng · 4U (80-84g) · G5
…và 14 sản phẩm khác.
Bạn muốn xem kỹ mẫu nào cứ gõ tên mẫu đó nhé.', '2026-11-10T21:56:42'),
(7, 3, 1, NULL, N'Lê Quốc Tuấn', N'Khuyến mãi hôm nay', '2026-11-10T21:56:47'),
(8, 3, 3, NULL, N'Trợ lý ảo', N'Mã giảm giá đang dùng được (nhập khi thanh toán, mỗi đơn 1 mã):
• Mã VCH7QX2YN: giảm 10% (tối đa 200.000 ₫) cho đơn từ 1.500.000 ₫, đến 18/11/2026
• Mã VCHFS500K: giảm 30.000 ₫ cho đơn từ 500.000 ₫, đến 23/11/2026
• Mã VCHSN26FS: giảm 15% (tối đa 300.000 ₫) cho đơn từ 1.000.000 ₫, đến 12/11/2026
• Mã VCHG30K01: giảm 30.000 ₫ cho đơn từ 600.000 ₫, đến 28/11/2026
• Mã VCHE7KL4B: giảm 25% (tối đa 250.000 ₫) cho đơn từ 300.000 ₫, đến 11/11/2026

Đợt giảm giá đang chạy (giá đã giảm sẵn trên sản phẩm):
• Sale vợt Yonex Astrox: giảm đến 10%, đến 12/11/2026
• Flash sale vợt cao cấp tháng 11: giảm đến 15%, đến 10/11/2026
• Tuần lễ vợt Mizuno: giảm đến 10%, đến 24/11/2026
• Ưu đãi vợt Kumpoo tháng 11: giảm đến 12%, đến 30/11/2026
• test: giảm đến 35%, đến 12/11/2026', '2026-11-10T21:56:47'),
(9, 3, 4, NULL, NULL, N'Đang kết nối với nhân viên. Bạn cứ nhắn câu hỏi, nhân viên sẽ trả lời ngay tại đây.', '2026-11-10T21:57:04'),
